package net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DescriptionVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property description of dcr initial access token ")
  void test_description_v_o_builder() {
    Assertions.assertFalse(DescriptionVO.nullValue().getDescription().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(DescriptionVO.tryFrom(null).getDescription().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", DescriptionVO.from("one").getDescription().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> DescriptionVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", DescriptionVO.from("one").toString());
  }
}
